record.field:
if inputs.PF and inputs.PF.amount > 0:
    result = - (inputs.PF.amount)
elif contract.apply_pf:
    custom_pf = contract.custom_monthly_pf or 0.0
    if custom_pf > 0:
        result = - round(custom_pf, 2)
    else:
        basic_wage = categories.BASIC if (categories.BASIC and categories.BASIC > 0) else contract.wage
        ceiling = contract.pf_wage_ceiling or 15000.0
        pf_base = min(basic_wage, ceiling) if contract.pf_enforce_ceiling else basic_wage
        rate = (contract.pf_employee_rate or 12.0) / 100.0
        pf_amount = round(pf_base * rate, 2)
        result = - pf_amount if pf_amount > 0 else 0.0
else:
    result = 0.0

if inputs.ESI and inputs.ESI.amount > 0:
    result = - (inputs.ESI.amount)
elif employee.apply_esi and contract.apply_esi:
    custom_esi = contract.custom_monthly_esi or 0.0
    if custom_esi > 0:
        result = - round(custom_esi, 2)
    else:
        gross = categories.GROSS if (categories.GROSS and categories.GROSS > 0) else contract.wage
        limit = contract.esi_wage_limit or 21000.0
        rate = (contract.esi_employee_rate or 0.75) / 100.0

        is_covered = False
        if gross <= limit:
            is_covered = True
        elif contract.esi_contribution_end and payslip.date_to <= contract.esi_contribution_end:
            if not contract.esi_contribution_start or payslip.date_from >= contract.esi_contribution_start:
                is_covered = True

        if is_covered:
            esi_amount = round(gross * rate, 2)
            result = - esi_amount if esi_amount > 0 else 0.0
        else:
            result = 0.0
else:
    result = 0.0
